deeper_reasoning_2:
\textbf{Deeper reasoning 2: Low transfer can only leave the low sector by exposing a high incoming momentum.}

\textbf{Claim.}
Let \(p,q\in P_{\mathrm L}\), let \(0<|r|<N^\delta\), and assume \(\delta<\alpha\). If \(p+q-r\notin P_{\mathrm L}\), then
\[
|M_{pqr}|\leq CN^{-2\alpha},
\qquad
\max\{|p|,|q|\}>N^\alpha/3,
\]
where
\[
M_{pqr}:=\langle\varphi_{p+q-r}\otimes\varphi_r,
\eta\varphi_p\otimes\varphi_q\rangle .
\]
Consequently every low-transfer correction term that leaves the low block is marked by the operator \(\mathcal N_{>N^{\alpha/3}}\).

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & P_{\mathrm L}=\{p\in\Lambda^\ast: |p|\leq N^\alpha\}.\\[1mm]
(P2) & p,q\in P_{\mathrm L},\quad 0<|r|<N^\delta,\quad \delta<\alpha,\quad p+q-r\notin P_{\mathrm L}.\\[1mm]
(P3) & \displaystyle
       |M_{pqr}|\leq
       \frac{C\,\mathbf 1_{(P_{\mathrm L}^2)^c}(p+q-r,r)\mathbf 1_{P_{\mathrm L}^2}(p,q)}
       {|p+q-r|^2+|r|^2}.\\[3mm]
(P4) & \text{For all sufficiently large }N,\quad N^\alpha-N^\delta\geq 2N^\alpha/3.\\[1mm]
(P5) & \text{If }A+B>S\text{ and }A,B\geq0,\text{ then }\max\{A,B\}>S/2.
\end{array}
\]

\textbf{Derivation.}
Because \((p+q-r)+r=p+q\), the coefficient obeys the momentum-conservation support condition in \((P3)\). Since \(p,q\in P_{\mathrm L}\) and \(p+q-r\notin P_{\mathrm L}\), the incoming pair is low while the outgoing pair is high. Therefore
\begin{align}
|M_{pqr}|
&\leq \frac{C}{|p+q-r|^2+|r|^2}\\
&\leq \frac{C}{|p+q-r|^2}
 < CN^{-2\alpha},
\end{align}
because \(p+q-r\notin P_{\mathrm L}\) implies \(|p+q-r|>N^\alpha\).

It remains to locate the price of this escape. The triangle inequality gives
\begin{align}
N^\alpha
&< |p+q-r|\\
&\leq |p|+|q|+|r|,
\end{align}
and hence
\begin{align}
|p|+|q|&>N^\alpha-|r|>N^\alpha-N^\delta. 
\end{align}
By \((P5)\),
\begin{align}
\max\{|p|,|q|\}&>\frac{N^\alpha-N^\delta}{2}\geq N^\alpha/3.
\end{align}
Thus each escaped coefficient necessarily contains at least one incoming annihilation operator acting on modes above \(N^{\alpha/3}\). In quadratic-form estimates this places the correction next to \(\mathcal N_{>N^{\alpha/3}}\), which is the decisive tail factor used to make the cross term negligible.

\textbf{Final Result.}
\[
\boxed{p+q-r\notin P_{\mathrm L},\ |r|<N^\delta< N^\alpha
\quad\Longrightarrow\quad
|M_{pqr}|\leq CN^{-2\alpha}\text{ and }\max\{|p|,|q|\}>N^\alpha/3.}
\]
\hfill$\blacksquare$

deeper_reasoning_4:
\textbf{Deeper reasoning 4: The renormalized interaction extracts exactly the scattering-energy scale.}

\textbf{Claim.}
If
\[
\alpha>\kappa,
\qquad
\kappa+3\alpha<1,
\qquad
3\kappa+2\alpha<1,
\]
then the renormalized low-sector interaction satisfies
\[
\langle\psi_N,\mathcal W_{\mathrm{ren}}\psi_N\rangle
\geq 4\pi aN^{1+\kappa}+o(N).
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & \displaystyle
       \mathcal W_{\mathrm{ren}}\geq
       4\pi aN^{1+\kappa}
       -CN^\kappa\mathcal N_{>N^\alpha}
       -CN^{\kappa+3\alpha}
       -CN^{2\kappa+2\alpha-1}(\mathcal K+
       \mathcal N).\\[2mm]
(P2) & \displaystyle
       \langle\psi_N,\mathcal N_{>N^\alpha}\psi_N\rangle
       \leq C N^{1+\kappa-2\alpha}.\\[1mm]
(P3) & \displaystyle
       \langle\psi_N,(\mathcal K+\mathcal N)\psi_N\rangle
       \leq C N^{1+\kappa}.\\[1mm]
(P4) & N^s=o(N)\text{ whenever }s<1.
\end{array}
\]

\textbf{Derivation.}
Take the expectation of \((P1)\) in \(\psi_N\). The high-momentum depletion error obeys
\begin{align}
N^\kappa\langle\mathcal N_{>N^\alpha}\rangle
&\leq C N^\kappa N^{1+\kappa-2\alpha}
 = C N^{1+2\kappa-2\alpha}.
\end{align}
This is \(o(N)\), because \(\alpha>\kappa\). The counting error obeys
\begin{align}
N^{\kappa+3\alpha}=o(N)
\end{align}
by \(\kappa+3\alpha<1\). Finally, the kinetic-number error obeys
\begin{align}
N^{2\kappa+2\alpha-1}
\langle\mathcal K+\mathcal N\rangle
&\leq C N^{2\kappa+2\alpha-1}N^{1+\kappa}
 = C N^{3\kappa+2\alpha},
\end{align}
which is \(o(N)\) by \(3\kappa+2\alpha<1\). Substituting these three bounds into \((P1)\) gives
\begin{align}
\langle\mathcal W_{\mathrm{ren}}\rangle
&\geq 4\pi aN^{1+\kappa}+o(N).
\end{align}
Thus the leading interaction energy survives exactly at the scattering length scale, while every low-sector truncation cost is sublinear.

\textbf{Final Result.}
\[
\boxed{\langle\psi_N,\mathcal W_{\mathrm{ren}}\psi_N\rangle
\geq 4\pi aN^{1+\kappa}+o(N).}
\]
\hfill$\blacksquare$

deeper_reasoning_5:
\textbf{Deeper reasoning 5: The three-body remainder is harmless because every term carries either a tail penalty or a subcritical exponent.}

\textbf{Claim.}
Suppose the three-body remainder has the ground-state estimate
\[
|\langle\psi_N,R_N\psi_N\rangle|
\leq C\sum_{j=1}^5 N^{t_j}+o(N),
\]
where
\[
\begin{array}{lll}
t_1=1+5\kappa-2\beta, &
 t_2=1/2+9\kappa/2+5\alpha/2-2\beta, &
 t_3=1+9\kappa/2+\beta/2-3\alpha/2,\\[1mm]
t_4=1/2+4\kappa+\alpha+\beta/2, &
 t_5=1+4\kappa+5\beta/2-5\alpha/2. &
\end{array}
\]
If \(t_j<1\) for all \(j\), then \(\langle\psi_N,R_N\psi_N\rangle=o(N)\).

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & \displaystyle
       |\langle R_N\rangle|\leq C\sum_{j=1}^5 N^{t_j}+o(N).\\[1mm]
(P2) & t_j<1\quad\text{for }1\leq j\leq5.\\[1mm]
(P3) & N^s=o(N)\text{ whenever }s<1.\\[1mm]
(P4) & \text{The exponents }t_j\text{ arise after applying kinetic-energy and high-momentum tail bounds to }R_N.
\end{array}
\]

\textbf{Derivation.}
By \((P2)\) and \((P3)\), each power satisfies \(N^{t_j}=o(N)\). Since there are only finitely many such terms,
\begin{align}
\sum_{j=1}^5 N^{t_j}=o(N).
\end{align}
The remainder estimate \((P1)\) therefore gives
\begin{align}
|\langle R_N\rangle|
&\leq C o(N)+o(N)=o(N).
\end{align}
The proof-theoretic value of this step is that it isolates exactly what must be checked about \(R_N\): not its detailed operator formula, but that every normal-ordered contribution is accompanied by enough powers of \(N^{-1}\), enough kinetic control, or enough high-momentum depletion to land below the linear scale.

\textbf{Final Result.}
\[
\boxed{\max_{1\leq j\leq5}t_j<1
\quad\Longrightarrow\quad
\langle\psi_N,R_N\psi_N\rangle=o(N).}
\]
\hfill$\blacksquare$

deeper_reasoning_7:
\textbf{Deeper reasoning 7: The final energy squeeze turns the lower bound into complete BEC.}

\textbf{Claim.}
Let \(0\leq\kappa<1/20\), let \(V\in L^1(\mathbb R^3)\) be compactly supported, radial, and non-negative, and let \(\psi_N\) be a normalized ground state of \(H_N\). Then
\[
\lim_{N\to\infty}\langle\varphi_0,\gamma_N^{(1)}\varphi_0\rangle=1.
\]

\textbf{Premises.}
\[
\begin{array}{ll}
(P1) & \displaystyle E_N:=\langle\psi_N,H_N\psi_N\rangle
       \leq 4\pi aN^{1+\kappa}+o(N).\\[1mm]
(P2) & \displaystyle H_N\geq\mathcal T_c+\mathcal W_{\mathrm{ren}}-R_N.\\[1mm]
(P3) & \displaystyle \langle\psi_N,\mathcal T_c\psi_N\rangle
       \geq 4\pi^2\langle\psi_N,\mathcal N_+\psi_N\rangle+o(N).\\[1mm]
(P4) & \displaystyle \langle\psi_N,\mathcal W_{\mathrm{ren}}\psi_N\rangle
       \geq 4\pi aN^{1+\kappa}+o(N).\\[1mm]
(P5) & \displaystyle |\langle\psi_N,R_N\psi_N\rangle|=o(N).\\[1mm]
(P6) & \displaystyle \mathcal N_+\geq0.\\[1mm]
(P7) & \displaystyle
       1-\langle\varphi_0,\gamma_N^{(1)}\varphi_0\rangle
       =N^{-1}\langle\psi_N,\mathcal N_+\psi_N\rangle.
\end{array}
\]

\textbf{Derivation.}
Taking the expectation of \((P2)\) in the ground state and using \((P3)\)--\((P5)\),
\begin{align}
E_N
&=\langle H_N\rangle\\
&\geq \langle\mathcal T_c\rangle+\langle\mathcal W_{\mathrm{ren}}\rangle-\langle R_N\rangle\\
&\geq 4\pi^2\langle\mathcal N_+\rangle+4\pi aN^{1+\kappa}+o(N).
\end{align}
Compare this with \((P1)\):
\begin{align}
4\pi aN^{1+\kappa}+o(N)
&\geq E_N\\
&\geq 4\pi aN^{1+\kappa}+4\pi^2\langle\mathcal N_+\rangle+o(N).
\end{align}
After subtracting the common leading term,
\begin{align}
4\pi^2\langle\mathcal N_+\rangle\leq o(N).
\end{align}
Since \(\mathcal N_+\geq0\), this implies
\begin{align}
\langle\psi_N,\mathcal N_+\psi_N\rangle=o(N).
\end{align}
Finally, \((P7)\) gives
\begin{align}
1-\langle\varphi_0,\gamma_N^{(1)}\varphi_0\rangle
&=N^{-1}\langle\psi_N,\mathcal N_+\psi_N\rangle\longrightarrow0.
\end{align}
Thus the zero-momentum occupation fraction converges to one.

\textbf{Final Result.}
\[
\boxed{\lim_{N\to\infty}\langle\varphi_0,\gamma_N^{(1)}\varphi_0\rangle=1.}
\]
\hfill$\blacksquare$
